const fs=require("fs");const c=JSON.parse(fs.readFileSync("evals/casos-adicionales.json","utf8"));
const us=[...JSON.parse(fs.readFileSync("data/api/estudiantes.json","utf8")).map(x=>["estudiante",x.id]),...JSON.parse(fs.readFileSync("data/api/coordinadores.json","utf8")).map(x=>["coordinador",x.id])];
let bad=0;for(const k of c){if(!us.some(u=>u[0]==k.usuario.rol&&u[1]==k.usuario.id)){console.log("user",k.id);bad++}
for(const ci of k.citasEsperadas){const t=fs.readFileSync("data/reglamento/"+ci.documento,"utf8").split(/\r?\n/);if(!t.includes("## "+ci.seccion)){console.log("cita",k.id);bad++}}}
console.log(c.length,"casos, errores",bad)
EOF
